SELECT CASE WHEN quantity >= 8 THEN 'high' WHEN quantity >= 5 THEN 'mid' ELSE 'low' END AS quantity_bucket, SUM(unit_price) AS total_unit_price, COUNT(DISTINCT quantity) AS unique_products FROM order_items WHERE product_id = 4 GROUP BY CASE WHEN quantity >= 8 THEN 'high' WHEN quantity >= 5 THEN 'mid' ELSE 'low' END HAVING COUNT(DISTINCT quantity) < 3 ORDER BY quantity_bucket, total_unit_price LIMIT 50;
